import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:flutter_secure_storage/flutter_secure_storage.dart';
import 'package:http/http.dart' as http;

const apiBase = String.fromEnvironment('EURO_API_URL', defaultValue: 'https://al-euro-cdzo.onrender.com');
const bg = Color(0xFF07090E), panel = Color(0xFF11151E), border = Color(0xFF293141), blue = Color(0xFF0A84FF), red = Color(0xFF8D2637), muted = Color(0xFF9AA6B7);
const secure = FlutterSecureStorage();

void main() => runApp(const EuroApp());
class EuroApp extends StatelessWidget {
  const EuroApp({super.key});
  @override Widget build(BuildContext context) => MaterialApp(
    title: 'EURO CARS', debugShowCheckedModeBanner: false,
    theme: ThemeData(brightness: Brightness.dark, scaffoldBackgroundColor: bg, colorScheme: const ColorScheme.dark(primary: blue, surface: panel), useMaterial3: true,
      inputDecorationTheme: InputDecorationTheme(filled: true, fillColor: panel, border: OutlineInputBorder(borderRadius: BorderRadius.circular(14), borderSide: const BorderSide(color: border)))),
    home: const Gate());
}
class Gate extends StatefulWidget { const Gate({super.key}); @override State<Gate> createState()=>_GateState(); }
class _GateState extends State<Gate> {
 String? token; Map<String,dynamic>? user; bool loading=true;
 @override void initState(){super.initState(); restore();}
 Future<void> restore() async { final t=await secure.read(key:'token'), u=await secure.read(key:'user'); if(t!=null&&u!=null){try{token=t;user=jsonDecode(u);}catch(_){await secure.deleteAll();}} if(mounted)setState(()=>loading=false); }
 Future<void> login(String t,Map<String,dynamic> u) async {await secure.write(key:'token',value:t);await secure.write(key:'user',value:jsonEncode(u));setState(()=>{token=t,user=u});}
 Future<void> logout() async {await secure.deleteAll();setState(()=>{token=null,user=null});}
 @override Widget build(BuildContext c)=>loading?const Scaffold(body:Center(child:CircularProgressIndicator())):token==null||user==null?Login(onLogin:login):Shop(token:token!,user:user!,onLogout:logout);
}
class Login extends StatefulWidget { final Future<void> Function(String,Map<String,dynamic>) onLogin; const Login({super.key,required this.onLogin}); @override State<Login> createState()=>_LoginState(); }
class _LoginState extends State<Login>{
 final phone=TextEditingController(),pass=TextEditingController(); String role='workshop'; bool busy=false; String? error;
 Future<void> submit() async {if(phone.text.trim().isEmpty||pass.text.isEmpty){setState(()=>error='أدخل رقم الموبايل وكلمة المرور');return;}setState(()=>{busy=true,error=null});try{final r=await http.post(Uri.parse('$apiBase/api/auth'),headers:{'Content-Type':'application/json'},body:jsonEncode({'mode':'login','client':'mobile','role':role,'phone':phone.text.trim(),'password':pass.text})).timeout(const Duration(seconds:30));final d=jsonDecode(r.body);if(r.statusCode<200||r.statusCode>=300)throw Exception(d['error']??'تعذر تسجيل الدخول');if(d['accessToken']==null||d['user']==null)throw Exception('الخادم لم يرجع جلسة تطبيق صالحة');await widget.onLogin(d['accessToken'].toString(),Map<String,dynamic>.from(d['user']));}catch(e){setState(()=>error=e.toString().replaceFirst('Exception: ',''));}finally{if(mounted)setState(()=>busy=false);}}
 @override void dispose(){phone.dispose();pass.dispose();super.dispose();}
 @override Widget build(BuildContext c)=>Directionality(textDirection:TextDirection.rtl,child:Scaffold(body:SafeArea(child:Center(child:SingleChildScrollView(padding:const EdgeInsets.all(24),child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:440),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[
 const Icon(Icons.directions_car_filled_rounded,color:red,size:60),const SizedBox(height:12),const Center(child:Text('EURO CARS',style:TextStyle(fontSize:28,fontWeight:FontWeight.w900,letterSpacing:2))),const SizedBox(height:6),const Center(child:Text('منصة قطع الصيانة للورشات',style:TextStyle(color:muted))),const SizedBox(height:32),
 SegmentedButton<String>(segments:const [ButtonSegment(value:'workshop',label:Text('حساب ورشة')),ButtonSegment(value:'marketer',label:Text('حساب مسوّق'))],selected:{role},onSelectionChanged:(v)=>setState(()=>role=v.first)),
 const SizedBox(height:16),TextField(controller:phone,keyboardType:TextInputType.phone,decoration:const InputDecoration(labelText:'رقم الموبايل',prefixIcon:Icon(Icons.phone))),const SizedBox(height:12),TextField(controller:pass,obscureText:true,onSubmitted:(_)=>submit(),decoration:const InputDecoration(labelText:'كلمة المرور',prefixIcon:Icon(Icons.lock_outline))),
 if(error!=null)Padding(padding:const EdgeInsets.only(top:12),child:Text(error!,style:const TextStyle(color:Colors.redAccent))),const SizedBox(height:18),FilledButton(onPressed:busy?null:submit,child:Padding(padding:const EdgeInsets.all(12),child:Text(busy?'جاري الدخول...':'تسجيل الدخول'))),const SizedBox(height:12),const Text('يلزم حساب مسجّل ومفعّل من إدارة EURO CARS.',textAlign:TextAlign.center,style:TextStyle(color:muted,fontSize:12))
 ])))))));
}
class Shop extends StatefulWidget {final String token;final Map<String,dynamic> user;final Future<void> Function() onLogout;const Shop({super.key,required this.token,required this.user,required this.onLogout});@override State<Shop> createState()=>_ShopState();}
class _ShopState extends State<Shop>{
 int tab=0;bool busy=false;String search='';String? error;List<Map<String,dynamic>> parts=[],orders=[];Map<String,int> cart={};Map<String,dynamic> account={};final searchCtl=TextEditingController();
 Future<Map<String,dynamic>> api(String path)async{final r=await http.get(Uri.parse('$apiBase$path'),headers:{'Authorization':'Bearer ${widget.token}'}).timeout(const Duration(seconds:30));final d=Map<String,dynamic>.from(jsonDecode(r.body));if(r.statusCode<200||r.statusCode>=300)throw Exception(d['error']??'تعذر تحميل البيانات');return d;}
 Future<void> loadParts()async{setState(()=>{busy=true,error=null});try{final d=await api('/api/parts');parts=List<Map<String,dynamic>>.from(d['parts']??[]);}catch(e){error=e.toString().replaceFirst('Exception: ','');}finally{if(mounted)setState(()=>busy=false);}}
 Future<void> loadOrders()async{setState(()=>busy=true);try{final d=await api('/api/orders');orders=List<Map<String,dynamic>>.from(d['orders']??[]);}catch(e){error=e.toString().replaceFirst('Exception: ','');}finally{if(mounted)setState(()=>busy=false);}}
 Future<void> loadAccount()async{setState(()=>busy=true);try{account=await api(widget.user['role']=='marketer'?'/api/marketer/dashboard':'/api/workshop/dashboard');}catch(e){error=e.toString().replaceFirst('Exception: ','');}finally{if(mounted)setState(()=>busy=false);}}
 Future<void> sendOrder(String pay)async{if(cart.isEmpty){setState(()=>error='السلة فارغة');return;}setState(()=>{busy=true,error=null});try{final req=http.MultipartRequest('POST',Uri.parse('$apiBase/api/orders'));req.headers['Authorization']='Bearer ${widget.token}';req.fields['items']=jsonEncode(cart);req.fields['pay']=pay;final streamed=await req.send().timeout(const Duration(seconds:30));final d=jsonDecode(await streamed.stream.bytesToString());if(streamed.statusCode<200||streamed.statusCode>=300)throw Exception(d['error']??'تعذر إرسال الطلب');cart={};error='تم إرسال الطلب بنجاح: ${d['orderNumber']??d['orderId']??''}';await loadOrders();if(mounted)setState(()=>tab=2);}catch(e){error=e.toString().replaceFirst('Exception: ','');}finally{if(mounted)setState(()=>busy=false);}}
 @override void initState(){super.initState();loadParts();}
 @override void dispose(){searchCtl.dispose();super.dispose();}
 @override Widget build(BuildContext c){final visible=parts.where((p)=>'${p['name']} ${p['brand']} ${p['pn']} ${p['model']}'.toLowerCase().contains(search.toLowerCase())).toList();final labels=['الكتالوج','السلة','طلباتي','حسابي'];return Directionality(textDirection:TextDirection.rtl,child:Scaffold(appBar:AppBar(backgroundColor:bg,title:const Text('EURO CARS',style:TextStyle(fontWeight:FontWeight.w900)),actions:[IconButton(onPressed:widget.onLogout,icon:const Icon(Icons.logout))]),bottomNavigationBar:NavigationBar(backgroundColor:panel,selectedIndex:tab,onDestinationSelected:(i){setState(()=>tab=i);if(i==2)loadOrders();if(i==3)loadAccount();},destinations:const [NavigationDestination(icon:Icon(Icons.grid_view),label:'الكتالوج'),NavigationDestination(icon:Icon(Icons.shopping_bag_outlined),label:'السلة'),NavigationDestination(icon:Icon(Icons.receipt_long),label:'طلباتي'),NavigationDestination(icon:Icon(Icons.person_outline),label:'حسابي')]),body:Column(children:[if(busy)const LinearProgressIndicator(),if(error!=null)Material(color:red.withValues(alpha:.25),child:ListTile(title:Text(error!),trailing:IconButton(onPressed:()=>setState(()=>error=null),icon:const Icon(Icons.close)))),Expanded(child:IndexedStack(index:tab,children:[catalog(visible),cartPage(),ordersPage(),accountPage()]))]));}
 Widget catalog(List<Map<String,dynamic>> list)=>RefreshIndicator(onRefresh:loadParts,child:ListView(padding:const EdgeInsets.all(16),children:[TextField(controller:searchCtl,onChanged:(v)=>setState(()=>search=v),decoration:const InputDecoration(hintText:'بحث باسم القطعة أو الماركة أو رقم OEM',prefixIcon:Icon(Icons.search))),const SizedBox(height:12),if(list.isEmpty)const Padding(padding:EdgeInsets.all(30),child:Text('لا توجد قطع مطابقة حالياً',style:TextStyle(color:muted))),...list.map((p){final id='${p['id']}';final n=cart[id]??0;return Card(color:panel,child:Padding(padding:const EdgeInsets.all(14),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('${p['name']??'قطعة'}',style:const TextStyle(fontWeight:FontWeight.bold,fontSize:16)),const SizedBox(height:5),Text('${p['brand']??''} · OEM ${p['pn']??'—'}',style:const TextStyle(color:muted)),const SizedBox(height:8),Text('${p['price']??0} $ · المتوفر ${p['stock']??0}',style:const TextStyle(color:blue,fontWeight:FontWeight.bold)),Row(children:[IconButton(onPressed:n==0?null:()=>setState(()=>cart[id]=n-1),icon:const Icon(Icons.remove_circle_outline)),Text('$n'),IconButton(onPressed:n>=(int.tryParse('${p['stock']}')??0)?null:()=>setState(()=>cart[id]=n+1),icon:const Icon(Icons.add_circle_outline,color:blue))])])));})]));
 Widget cartPage(){final selected=parts.where((p)=>(cart['${p['id']}']??0)>0).toList();final total=selected.fold<double>(0,(s,p)=>s+(double.tryParse('${p['price']}')??0)*(cart['${p['id']}']??0));final marketer=widget.user['role']=='marketer';return ListView(padding:const EdgeInsets.all(16),children:[const Text('سلة الطلب',style:TextStyle(fontSize:22,fontWeight:FontWeight.bold)),...selected.map((p)=>ListTile(title:Text('${p['name']} × ${cart['${p['id']}']}'),subtitle:Text('${p['price']} $'))),ListTile(title:const Text('الإجمالي'),trailing:Text('${total.toStringAsFixed(2)} $',style:const TextStyle(color:blue))),if(selected.isEmpty)const Text('أضف القطع من الكتالوج أولاً',style:TextStyle(color:muted)),FilledButton(onPressed:busy||selected.isEmpty?null:()=>sendOrder('cod'),child:const Text('الدفع عند الاستلام')),if(!marketer)OutlinedButton(onPressed:busy||selected.isEmpty?null:()=>sendOrder('sham'),child:const Text('شام كاش')),if(!marketer)OutlinedButton(onPressed:busy||selected.isEmpty?null:()=>sendOrder('debt'),child:const Text('دفتر الدين للورشة'))]);}
 Widget ordersPage()=>RefreshIndicator(onRefresh:loadOrders,child:ListView(padding:const EdgeInsets.all(16),children:[const Text('طلباتي',style:TextStyle(fontSize:22,fontWeight:FontWeight.bold)),if(orders.isEmpty)const Text('لا توجد طلبات لعرضها',style:TextStyle(color:muted)),...orders.map((o)=>Card(color:panel,child:ListTile(leading:const Icon(Icons.receipt_long,color:blue),title:Text('طلب #${o['order_number']??o['id']??'—'}'),subtitle:Text('${o['status']??'—'}'),trailing:Text('${o['total_amount']??''} $')))]));
 Widget accountPage(){final u=Map<String,dynamic>.from(account['user']??{});return RefreshIndicator(onRefresh:loadAccount,child:ListView(padding:const EdgeInsets.all(16),children:[Text('أهلاً ${widget.user['name']??''}',style:const TextStyle(fontSize:22,fontWeight:FontWeight.bold)),Text('${widget.user['phone']??''}',style:const TextStyle(color:muted)),const SizedBox(height:18),if(widget.user['role']=='marketer')...[_metric('كود الإحالة','${widget.user['my_ref_code']??'—'}'),_metric('العمولات','${account['commissions']??'تظهر حسب بيانات الحساب'}')]else...[_metric('التصنيف','${u['tier']??widget.user['tier']??'—'}'),_metric('حد الدين','${u['debt_limit']??widget.user['debt_limit']??0} $'),_metric('الرصيد المستحق','${u['debt_balance']??widget.user['debt_balance']??0} $')],OutlinedButton.icon(onPressed:loadAccount,icon:const Icon(Icons.refresh),label:const Text('تحديث بيانات الحساب')),OutlinedButton.icon(onPressed:widget.onLogout,icon:const Icon(Icons.logout),label:const Text('تسجيل الخروج'))]));}
 Widget _metric(String k,String v)=>Card(color:panel,child:ListTile(title:Text(k,style:const TextStyle(color:muted)),trailing:Text(v,style:const TextStyle(color:blue,fontWeight:FontWeight.bold))));
}
